arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now defaults to UTF-8 with the EFS
        // flag set. Explicitly specify Shift_JIS for the legacy Java consumer.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("Shift_JIS"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: keyed and non-keyed service registrations are
// no longer interchangeable. Register as keyed to match [FromKeyedServices("cache")].
services.AddKeyedSingleton<ICache, RedisCache>("cache");

